const d = n => new Date(Date.now() - n*86400000).toISOString().slice(0,10);
const daysSince = s => Math.floor((Date.now() - new Date(s).getTime())/86400000);
return $input.all().map(({json}) => {
 const days_inactive = daysSince(json.last_visit);
 const risk = days_inactive >= 30 ? 'high' : days_inactive >= 14 ? 'medium' : 'none';
 return {json: {...json, days_inactive, risk, needs_action: risk !== 'none', reason: risk === 'none' ? 'active member' : `${days_inactive} days without a visit`}};
});

return $input.all().map(({json}) => {
 const first = json.name.split(' ')[0];
 const offer = json.risk === 'high' ? 'Would a free session with a coach help you get back into it? Reply YES and we will book it.' : 'Is there a class or time slot that would suit you better? Just reply to this email.';
 const message = `Hi ${first}, we have not seen you at Ironside for ${json.days_inactive} days and wanted to check in. ${offer} This message was prepared by an automated assistant.`;
 return {json: {...json, channel:'email', to: json.email, subject:'We miss you at Ironside', message, approval: json.risk === 'high' ? 'owner_approves' : 'auto_send'}};
});
